'use strict';

/**
* Create a named scale.
*
* @module @stdlib/plot/vega/scale/named
*
* @example
* var namedScale = require( '@stdlib/plot/vega/scale/named' );
*
* var scale = namedScale( 'linear', 'xScale' );
* // returns <LinearScale>
*
* @example
* var namedScale = require( '@stdlib/plot/vega/scale/named' );
*
* var xScale = namedScale.factory( 'linear', 'xScale' );
*
* var scale = xScale();
* // returns <LinearScale>
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var factory = require( './factory.js' );
var main = require( './main.js' );


// MAIN //

setReadOnly( main, 'factory', factory );


// EXPORTS //

module.exports = main;

// exports: { "factory": "main.factory" }
